    @Lock(LockModeType.PESSIMISTIC_WRITE)
    @Query("select l from Loan l where l.id = :loanId")
    Optional<Loan> findByIdForUpdate(@Param("loanId") UUID loanId);

    @Query(value = "select new com.example.lending.adapter.out.persistence.ActiveLoanRow(l.id, l.bookId, b.title, l.loanedAt, l.dueAt) "
            + "from Loan l left join Book b on b.id = l.bookId "
            + "where l.memberId = :memberId and l.returnedAt is null "
            + "order by l.loanedAt, l.id",
            countQuery = "select count(l) from Loan l where l.memberId = :memberId and l.returnedAt is null")
    Page<ActiveLoanRow> findActiveLoanRowsByMemberId(@Param("memberId") UUID memberId, Pageable pageable);

    @Query("select new com.example.lending.adapter.out.persistence.LoanHistoryRow(l.id, l.bookId, b.title, l.loanedAt, l.dueAt, l.returnedAt) "
            + "from Loan l left join Book b on b.id = l.bookId "
            + "where l.memberId = :memberId "
            + "order by l.loanedAt desc, l.id desc")
    List<LoanHistoryRow> findLoanHistoryRowsByMemberId(@Param("memberId") UUID memberId);
}
