import com.example.lending.application.port.in.ListMemberLoansUseCase.ActiveLoanPage;
import com.example.lending.application.port.out.LoadLoanPort;
import com.example.lending.application.port.out.SaveLoanPort;
import com.example.lending.domain.Loan;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.PageRequest;
import org.springframework.stereotype.Component;

import java.util.List;
import java.util.Optional;
import java.util.UUID;

@Component
public class LoanPersistenceAdapter implements LoadLoanPort, SaveLoanPort {

    private final LoanJpaRepository loanJpaRepository;

    public LoanPersistenceAdapter(LoanJpaRepository loanJpaRepository) {
        this.loanJpaRepository = loanJpaRepository;
    }

    @Override
    public long countActiveByMemberId(UUID memberId) {
        return loanJpaRepository.countByMemberIdAndReturnedAtIsNull(memberId);
    }

    @Override
    public Optional<Loan> loadLoan(UUID loanId) {
        return loanJpaRepository.findById(loanId);
    }

    @Override
    public Optional<Loan> loadLoanForUpdate(UUID loanId) {
        return loanJpaRepository.findByIdForUpdate(loanId);
    }

    @Override
    public ActiveLoanPage loadActiveLoans(UUID memberId, int page, int size) {
        Page<ActiveLoanRow> rows = loanJpaRepository.findActiveLoanRowsByMemberId(memberId, PageRequest.of(page, size));
        List<ActiveLoan> items = rows.getContent().stream()
                .map(row -> new ActiveLoan(row.loanId(), row.bookId(), row.title(), row.loanedAt(), row.dueAt()))
                .toList();
        return new ActiveLoanPage(items, page, size, rows.getTotalElements());
    }

    @Override
    public List<LoanHistoryItem> loadLoanHistory(UUID memberId) {
        return loanJpaRepository.findLoanHistoryRowsByMemberId(memberId).stream()
                .map(row -> toLoanHistoryItem(memberId, row))
                .toList();
    }

    // 연체료 계산 규칙은 도메인 Loan 에 두고, 여기서는 그 결과만 옮긴다.
    private LoanHistoryItem toLoanHistoryItem(UUID memberId, LoanHistoryRow row) {
        Long lateFee = row.returnedAt() == null ? null
                : Loan.reconstitute(row.loanId(), row.bookId(), memberId, row.loanedAt(), row.dueAt(), row.returnedAt(), null)
                .lateFee();
        return new LoanHistoryItem(row.loanId(), row.title(), row.loanedAt(), row.returnedAt(), lateFee);
    }

    @Override
    public void saveLoan(Loan loan) {
        loanJpaRepository.save(loan);
    }
}
package com.example.lending.adapter.out.persistence;

import com.example.lending.domain.Loan;
import jakarta.persistence.LockModeType;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Lock;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

import java.util.List;
import java.util.Optional;
import java.util.UUID;

public interface LoanJpaRepository extends JpaRepository<Loan, UUID> {

    long countByMemberIdAndReturnedAtIsNull(UUID memberId);

    @Lock(LockModeType.PESSIMISTIC_WRITE)
    @Query("select l from Loan l where l.id = :loanId")
    Optional<Loan> findByIdForUpdate(@Param("loanId") UUID loanId);

    @Query(value = "select new com.example.lending.adapter.out.persistence.ActiveLoanRow(l.id, l.bookId, b.title, l.loanedAt, l.dueAt) "
            + "from Loan l left join Book b on b.id = l.bookId "
            + "where l.memberId = :memberId and l.returnedAt is null "
            + "order by l.loanedAt, l.id",
            countQuery = "select count(l) from Loan l where l.memberId = :memberId and l.returnedAt is null")
    Page<ActiveLoanRow> findActiveLoanRowsByMemberId(@Param("memberId") UUID memberId, Pageable pageable);

    @Query("select new com.example.lending.adapter.out.persistence.LoanHistoryRow(l.id, l.bookId, b.title, l.loanedAt, l.dueAt, l.returnedAt) "
            + "from Loan l left join Book b on b.id = l.bookId "
            + "where l.memberId = :memberId "
            + "order by l.loanedAt desc, l.id desc")
    List<LoanHistoryRow> findLoanHistoryRowsByMemberId(@Param("memberId") UUID memberId);
}
package com.example.lending.adapter.out.persistence;

import com.example.lending.application.port.out.LoadReservationPort;
