    public Member suspendMember(UUID memberId) {
        // 회원 행을 잠가 진행 중인 대출 요청과 정지 처리가 서로의 검사를 빠져나가지 못하게 한다.
        Member member = loadMemberPort.loadMemberForUpdate(memberId)
                .orElseThrow(() -> new MemberNotFoundException(memberId));
        member.suspend();
        saveMemberPort.saveMember(member);
        return member;
    }

    @Override
    public Member unsuspendMember(UUID memberId) {
        Member member = loadMemberPort.loadMemberForUpdate(memberId)
                .orElseThrow(() -> new MemberNotFoundException(memberId));
        member.unsuspend();
        saveMemberPort.saveMember(member);
        return member;
    }
}

